create function public.business_crm_workspace(p_hash text,p_slug text,p_view text,p_page integer default 1) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.business_accounts%rowtype;rows jsonb;totals jsonb;stages jsonb:='[]';total bigint;today date:=(now() at time zone 'Asia/Ho_Chi_Minh')::date;
begin
 a:=public.business_assert_session(p_hash,p_slug);perform public.business_assert_kind(a.tenant_id,'opportunities');perform public.business_assert_report_access(a.id,array['crm','people','sales','inventory']);
 if p_view is null or p_view not in ('pipeline','quotes','tickets','campaigns') or p_page is null or p_page not between 1 and 100000 then raise exception 'BUSINESS_INVALID_INPUT';end if;
 perform public.business_assert_kind(a.tenant_id,case p_view when 'quotes' then 'customer_quotes' when 'tickets' then 'support_tickets' when 'campaigns' then 'campaigns' else 'opportunities' end);
 if p_view='pipeline' then
  with r as (select o.id,o.code,o.name,p.name customer,s.name owner,o.stage,o.expected_amount,round(o.expected_amount*o.probability/100,4) weighted,o.probability,o.expected_close_on,o.next_contact_on from public.business_opportunities o join public.business_tenant_partners p on p.tenant_id=o.tenant_id and p.id=o.partner_id join public.business_staff s on s.tenant_id=o.tenant_id and s.id=o.owner_staff_id where o.tenant_id=a.tenant_id and o.status='active')
  select count(*),jsonb_build_object('open',count(*) filter(where stage not in ('won','lost')),'expected',coalesce(sum(expected_amount) filter(where stage not in ('won','lost')),0),'weighted',coalesce(sum(weighted) filter(where stage not in ('won','lost')),0),'overdue',count(*) filter(where stage not in ('won','lost') and next_contact_on<today)),coalesce((select jsonb_agg(to_jsonb(x)) from(select * from r order by expected_close_on,id limit 25 offset (p_page-1)*25)x),'[]') into total,totals,rows from r;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]') into stages from(select stage,count(*) count,coalesce(sum(expected_amount),0) amount from public.business_opportunities where tenant_id=a.tenant_id and status='active' group by stage order by stage)x;
 elsif p_view='quotes' then
  with r as(select q.id,q.code,q.name,p.name customer,q.revision,q.status,q.commercial_state stage,q.document_date,q.valid_until,q.total_amount,coalesce((select sum(c.total_amount) from public.business_sales_contracts c where c.tenant_id=q.tenant_id and c.quote_id=q.id and c.status='posted'),0) contracted from public.business_customer_quotes q join public.business_tenant_partners p on p.tenant_id=q.tenant_id and p.id=q.partner_id where q.tenant_id=a.tenant_id and q.status<>'cancelled')
  select count(*),jsonb_build_object('pending',count(*) filter(where status='posted' and stage='prepared' and valid_until>=today),'expired',count(*) filter(where status='posted' and stage='prepared' and valid_until<today),'accepted',count(*) filter(where stage='accepted' and status='posted'),'contracted',coalesce(sum(contracted),0)),coalesce((select jsonb_agg(to_jsonb(x)) from(select * from r order by document_date desc,id limit 25 offset (p_page-1)*25)x),'[]') into total,totals,rows from r;
 elsif p_view='tickets' then
  with r as(select t.id,t.code,t.name,p.name customer,s.name owner,t.stage,t.priority,t.opened_on,t.response_due_on,t.resolve_due_on,t.first_response_on,t.resolved_on,t.escalated,(t.stage not in ('closed','resolved') and t.resolve_due_on<today) or (t.first_response_on is null and t.response_due_on<today) overdue from public.business_support_tickets t join public.business_tenant_partners p on p.tenant_id=t.tenant_id and p.id=t.partner_id join public.business_staff s on s.tenant_id=t.tenant_id and s.id=t.owner_staff_id where t.tenant_id=a.tenant_id and t.status='active')
  select count(*),jsonb_build_object('open',count(*) filter(where stage not in ('closed','resolved')),'overdue',count(*) filter(where overdue),'answered',count(*) filter(where first_response_on is not null),'answeredOnTime',count(*) filter(where first_response_on<=response_due_on),'resolved',count(*) filter(where resolved_on is not null),'resolvedOnTime',count(*) filter(where resolved_on<=resolve_due_on)),coalesce((select jsonb_agg(to_jsonb(x)) from(select * from r order by overdue desc,resolve_due_on,id limit 25 offset (p_page-1)*25)x),'[]') into total,totals,rows from r;
 else
  with r as(select c.id,c.code,c.name,c.channel,c.budget,c.actual_spend,(select count(*) from public.business_leads where tenant_id=c.tenant_id and campaign_id=c.id and status='active') leads,(select count(*) from public.business_leads where tenant_id=c.tenant_id and campaign_id=c.id and status='active' and stage='converted') converted from public.business_campaigns c where c.tenant_id=a.tenant_id and c.status='active')
  select count(*),jsonb_build_object('spend',coalesce(sum(actual_spend),0),'leads',coalesce(sum(leads),0),'converted',coalesce(sum(converted),0),'costPerLead',case when sum(leads)>0 then round(sum(actual_spend)/sum(leads),0) else null end),coalesce((select jsonb_agg(to_jsonb(x)) from(select *,case when leads>0 then round(actual_spend/leads,0) end cost_per_lead from r order by name,id limit 25 offset (p_page-1)*25)x),'[]') into total,totals,rows from r;
 end if;
 return jsonb_build_object('rows',rows,'totals',totals,'stages',stages,'total',total,'page',p_page,'pageSize',25,'asOf',now());
end $$;
revoke all on function public.business_crm_workspace(text,text,text,integer) from public,anon,authenticated,service_role;
grant execute on function public.business_crm_workspace(text,text,text,integer) to service_role;
